  const out = {};
  const g = await page.request.get('/__test/clock'); out.get = [g.status(), await g.text()];
  out.now = await page.evaluate(() => [new Date().toString(), Intl.DateTimeFormat().resolvedOptions().timeZone]);
  const set = async (at) => { const r = await page.request.post('/__test/clock', {data:{at}}); return [r.status(), await r.text()]; };
  out.s1 = await set('2026-03-10T21:59:00-05:00');
  await page.goto('/slots');
  out.t1 = await page.getByText('Closed').count();
  out.s2 = await set('2026-03-10T22:00:00-05:00');
  await page.goto('/slots');
  out.t2 = await page.getByText('Closed').count();
  out.closedLabels = await page.getByRole('radio', {name: /Closed/}).evaluateAll(els=>els.map(e=>e.getAttribute('aria-label')||e.parentElement.innerText).slice(0,3));
  return out;
}

