async (page) => {
  const out = {};
  const snap = async () => ({
    hdr: await page.getByRole('link', {name: /Basket \(/}).innerText(),
    lines: await page.getByTestId('basket-line').evaluateAll(l=>l.map(e=>e.innerText.replace(/\s+/g,' '))),
    t: await page.getByTestId('totals').innerText().then(s=>s.replace(/\s+/g,' ')),
    blocked: await page.getByTestId('checkout-blocked').allInnerTexts().catch(()=>null),
    btnDisabled: await page.getByRole('button',{name:'Checkout'}).isDisabled(),
  });
  const reset = async () => { await page.request.post('/__test/reset'); await page.goto('/'); };
  const add = async (n, times=1, weight) => { for (let i=0;i<times;i++){ const a=page.getByRole('article',{name:n}); if(weight) await a.getByLabel(/Weight of/).selectOption({label:weight}); await a.getByRole('button',{name:'Add'}).click(); await page.goto('/'); } };
  // A: loose add 250g twice, tomatoes 250g = 1.1225 -> 1.12 ; apples 250g
  await reset();
  await add('Vine tomatoes, loose',1,'250 g');
  await page.goto('/basket'); out.tom250 = await snap();
  await page.goto('/'); await add('Vine tomatoes, loose',1,'250 g');
  await page.goto('/basket'); out.tom500 = await snap();
  // minus on loose
  await page.getByRole('button',{name:'Remove one Vine tomatoes, loose'}).click(); out.tomMinus = await snap();
  await page.getByRole('button',{name:'Remove one Vine tomatoes, loose'}).click(); out.tomMinus2 = await snap();
  // B: bananas 750g = 1.0425 -> 1.04; 1500g bananas 2.085->2.09 (float?) 
  await reset(); await add('Bananas, loose',1,'750 g'); await page.goto('/basket'); out.ban750 = await snap();
  await reset(); await add('Bananas, loose',1,'1500 g'); await page.goto('/basket'); out.ban1500 = await snap();
  await reset(); await add('Gala apples, loose',1,'250 g'); await page.goto('/basket'); out.apple250 = await snap();
  // C: voucher
  await reset(); await add('Natural yoghurt 500 g',3); await add('Sourdough loaf',2); await page.goto('/basket');
  await page.getByLabel('Voucher code').fill('SAVE10'); await page.getByRole('button',{name:'Apply'}).click(); out.voucher = await snap();
  out.voucherMsg = await page.locator('main').innerText();
  // D: quantity update
  await reset(); await add('Sourdough loaf',1); await page.goto('/basket');
  await page.getByLabel('Quantity of Sourdough loaf').fill('8'); await page.getByRole('button',{name:'Update Sourdough loaf'}).click(); out.qty8 = await snap();
  await page.getByRole('button',{name:'Remove one Sourdough loaf'}).click(); out.qty7 = await snap();
  return out;
}

