    await page.goto("/slots");
    await expect(slotRadio(page, "Wed, Mar 11 08:00 to 09:00, $2.99")).toBeEnabled();
    await expect(page.getByText("Closed")).toHaveCount(0);

    // 2. Clock 22:00, reload /slots.
